# Covers: MEM-005
# Requirement: `python scripts/make_synthetic_fixtures.py` deterministically and
# idempotently generates the demo fixtures (a 1024x768 EXIF-free synthetic shelf
# photo plus replayable segment/spark_json/image_edit responses keyed by the
# photo's sha256), lists every generated file in fixtures/MANIFEST.md with its
# source and license, and the whole fixture tree passes the pre-commit scan so it
# can be committed and replayed offline in fixture mode. The committed fixtures/
# tree matches what the generator produces (line endings aside), and running the
# tests never rewrites the working-tree fixtures.
import hashlib
import io
import os
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parents[1]
COMMITTED = REPO / "fixtures"
TEXT_SUFFIXES = {".md", ".txt", ".json"}
SOURCE_TEXT = "synthetic, generated by scripts/make_synthetic_fixtures.py"
LICENSE_TEXT = "MIT (own work)"


def _env():
    env = dict(os.environ)
    src = str(REPO / "src")
    env["PYTHONPATH"] = src + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
    return env


def _run_script(name, *args, root=REPO):
    return subprocess.run(
        [sys.executable, str(root / "scripts" / name), *args],
        cwd=str(root),
        env=_env(),
        capture_output=True,
        text=True,
        timeout=120,
    )


def _snapshot(root):
    return {p.relative_to(root).as_posix(): p.read_bytes() for p in sorted(root.rglob("*")) if p.is_file()}


def _normalized(snap):
    return {k: v.replace(b"\r\n", b"\n") if Path(k).suffix in TEXT_SUFFIXES else v for k, v in snap.items()}


@pytest.fixture(scope="module")
def sandbox(tmp_path_factory):
    """Copy of the generator in a temp root; it writes to <root>/fixtures, never the repo's."""
    root = tmp_path_factory.mktemp("fixturegen")
    (root / "scripts").mkdir()
    shutil.copy2(REPO / "scripts" / "make_synthetic_fixtures.py", root / "scripts")
    return root


@pytest.fixture(scope="module")
def generated(sandbox):
    committed_before = _snapshot(COMMITTED)
    first = _run_script("make_synthetic_fixtures.py", root=sandbox)
    assert first.returncode == 0, f"first run failed: {first.stdout}\n{first.stderr}"
    snap1 = _snapshot(sandbox / "fixtures")
    second = _run_script("make_synthetic_fixtures.py", root=sandbox)
    assert second.returncode == 0, f"second run failed: {second.stdout}\n{second.stderr}"
    snap2 = _snapshot(sandbox / "fixtures")
    assert _snapshot(COMMITTED) == committed_before, "generator touched the repo's fixtures/"
    return snap1, snap2


@pytest.fixture(scope="module")
def fixtures_dir(sandbox, generated):
    return sandbox / "fixtures"


@pytest.fixture(scope="module")
def photo_sha(fixtures_dir):
    return hashlib.sha256((fixtures_dir / "demo" / "photo.jpg").read_bytes()).hexdigest()


def test_second_run_leaves_identical_bytes(generated):
    snap1, snap2 = generated
    assert snap1, "script produced no files under fixtures/"
    assert sorted(snap1) == sorted(snap2)
    changed = [k for k in snap1 if snap1[k] != snap2[k]]
    assert changed == []


def test_committed_fixtures_match_generator_output(generated):
    snap1, _ = generated
    assert _normalized(_snapshot(COMMITTED)) == _normalized(snap1)


def test_photo_is_1024x768_jpeg_without_exif(fixtures_dir):
    from PIL import Image

    data = (fixtures_dir / "demo" / "photo.jpg").read_bytes()
    assert b"Exif\x00\x00" not in data
    with Image.open(io.BytesIO(data)) as img:
        assert img.format == "JPEG"
        assert img.size == (1024, 768)
        assert len(img.getexif()) == 0


def test_manifest_lists_every_fixture_file(generated, fixtures_dir):
    snap1, _ = generated
    manifest = fixtures_dir / "MANIFEST.md"
    assert manifest.is_file()
    text = manifest.read_text(encoding="utf-8")
    expected = [k for k in snap1 if k != "MANIFEST.md"]
    assert "demo/photo.jpg" in expected
    assert any(k.startswith("replay/") for k in expected)
    missing = [k for k in expected if k not in text]
    assert missing == []


def test_manifest_states_source_and_license(fixtures_dir):
    text = (fixtures_dir / "MANIFEST.md").read_text(encoding="utf-8")
    assert SOURCE_TEXT in text
    assert LICENSE_TEXT in text


@pytest.mark.parametrize("phrase", ["book", "mug", "lamp"])
def test_fixture_backend_replays_segment(fixtures_dir, photo_sha, phrase):
    from memripal.backend import FixtureBackend

    out = FixtureBackend(fixtures_dir / "replay").segment(photo_sha, phrase)
    assert isinstance(out, str)
    assert out.strip() != ""


def test_fixture_backend_replays_spark_json_phrases(fixtures_dir, photo_sha):
    from memripal.backend import FixtureBackend

    out = FixtureBackend(fixtures_dir / "replay").spark_json(photo_sha, "phrases")
    assert isinstance(out, dict)
    assert isinstance(out.get("phrases"), list)
    assert out["phrases"], "phrases list is empty"
    assert all(isinstance(p, str) and p for p in out["phrases"])


def test_fixture_backend_replays_book_image_edit_as_exif_free_webp(fixtures_dir, photo_sha):
    from memripal.backend import FixtureBackend

    out = FixtureBackend(fixtures_dir / "replay").image_edit(photo_sha, "book")
    assert isinstance(out, bytes)
    assert out[:4] == b"RIFF" and out[8:12] == b"WEBP"
    assert b"Exif" not in out


def test_precommit_scan_passes_over_all_fixtures(generated, fixtures_dir):
    snap1, _ = generated
    paths = [str(fixtures_dir / k) for k in snap1]
    result = _run_script("precommit_scan.py", *paths)
    assert result.returncode == 0, result.stderr


# Covers: MEM-017
# Requirement: the regenerated demo replays end to end through the real upload path. The
# generator records >= 12 Spark phrases plus one SAM response per phrase, all keyed by the
# requests find_loci derives from process_upload(photo.jpg) -- i.e. by the PROCESSED photo's
# sha, not the raw file's -- so FixtureBackend serves >= 10 loci for the demo offline, and
# the committed fixtures/MANIFEST.md lists every committed fixture file, one segment replay
# per phrase included.
@pytest.fixture(scope="module")
def demo_result(fixtures_dir):
    from memripal.backend import FixtureBackend
    from memripal.imaging import process_upload
    from memripal.loci import find_loci

    processed = process_upload((fixtures_dir / "demo" / "photo.jpg").read_bytes())
    progressed: list[str] = []
    # A frozen clock keeps the deadline out of play: replay is judged on keys alone.
    result = find_loci(
        FixtureBackend(fixtures_dir / "replay"),
        processed,
        on_progress=progressed.append,
        clock=lambda: 0.0,
    )
    return result, progressed


class TestDemoReplayForLoci:
    def test_replay_keyed_by_processed_sha_covers_at_least_12_phrases(self, demo_result):
        result, progressed = demo_result
        assert len(result.phrases) >= 12
        assert sorted(progressed) == sorted(result.phrases)

    def test_fixture_backend_serves_at_least_ten_loci_for_demo(self, demo_result):
        result, _ = demo_result
        assert len(result.loci) >= 10
        assert [lc.n for lc in result.loci] == list(range(1, len(result.loci) + 1))
        assert all(lc.label for lc in result.loci)

    def test_committed_manifest_lists_every_fixture_and_12_segment_replays(self):
        text = (COMMITTED / "MANIFEST.md").read_text(encoding="utf-8")
        files = [k for k in _snapshot(COMMITTED) if k != "MANIFEST.md"]
        missing = [k for k in files if f"`{k}`" not in text]
        assert missing == []
        segments = [k for k in files if k.startswith("replay/segment/")]
        assert len(segments) >= 12


# Covers: MEM-017
# Requirement: the demo replay fixtures are keyed by the sha256 of process_upload(photo.jpg), so
# that processed sha is pinned to a literal: a regenerated demo photo or an imaging/Pillow change
# that alters the processed bytes fails here loudly instead of surfacing as a silent
# "fixture_missing" at demo time. Changing the pin requires regenerating the replay fixtures.
DEMO_PROCESSED_SHA = "7af10a4e9efede5539af090a5c61550d34c8828cd1cbd956023fff088ca05206"


class TestDemoProcessedShaPin:
    def test_committed_demo_photo_processed_sha_is_pinned(self):
        from memripal.imaging import process_upload

        processed = process_upload((COMMITTED / "demo" / "photo.jpg").read_bytes())
        assert processed.sha == DEMO_PROCESSED_SHA
        assert (processed.width, processed.height) == (1024, 768)
